package com.asisten.bantu;
import android.Manifest; import android.content.pm.PackageManager; import android.graphics.Bitmap; import android.graphics.Color; import android.os.Bundle; import android.speech.tts.TextToSpeech; import android.widget.Button; import android.widget.TextView; import android.widget.Toast;
import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.camera.core.*; import androidx.camera.lifecycle.ProcessCameraProvider; import androidx.camera.view.PreviewView; import androidx.core.app.ActivityCompat; import androidx.core.content.ContextCompat;
import com.google.common.util.concurrent.ListenableFuture; import com.google.mlkit.vision.common.InputImage; import com.google.mlkit.vision.text.TextRecognition; import com.google.mlkit.vision.text.latin.TextRecognizerOptions; import com.google.mlkit.vision.face.FaceDetection; import com.google.mlkit.vision.face.FaceDetectorOptions;
import java.util.Locale; import java.util.concurrent.Executor;
public class VisionActivity extends AppCompatActivity implements TextToSpeech.OnInitListener {
private PreviewView previewView; private TextView tvResult; private TextToSpeech tts; private String mode="money"; private ImageCapture imageCapture; private ProcessCameraProvider cameraProvider; private Executor mainExecutor;
@Override protected void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_vision);previewView=findViewById(R.id.previewView);tvResult=findViewById(R.id.tvVisionResult);Button a=findViewById(R.id.btnCapture);Button b=findViewById(R.id.btnClose);mode=getIntent().getStringExtra("mode");if(mode==null)mode="money";tts=new TextToSpeech(this,this);mainExecutor=ContextCompat.getMainExecutor(this);a.setOnClickListener(v->capture());b.setOnClickListener(v->finish());if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},101);else startCamera();}
private void startCamera(){ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{cameraProvider=f.get();Preview p=new Preview.Builder().build();p.setSurfaceProvider(previewView.getSurfaceProvider());imageCapture=new ImageCapture.Builder().build();cameraProvider.unbindAll();cameraProvider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,p,imageCapture);}catch(Exception e){Toast.makeText(this,"Gagal kamera",Toast.LENGTH_SHORT).show();}},mainExecutor);}
private void capture(){if(imageCapture==null)return;tvResult.setText("⏳ Menganalisis...");imageCapture.takePicture(mainExecutor,new ImageCapture.OnImageCapturedCallback(){@Override public void onCaptureSuccess(@NonNull ImageProxy image){Bitmap bm=image.toBitmap();image.close();if("money".equals(mode))analyzeMoney(bm);else if("color".equals(mode))analyzeColor(bm);else if("face".equals(mode))analyzeFace(bm);else if("ktp".equals(mode))analyzeKtp(bm);} @Override public void onError(@NonNull ImageCaptureException e){tvResult.setText("Gagal");}});}
private void analyzeMoney(Bitmap bm){InputImage img=InputImage.fromBitmap(bm,0);TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS).process(img).addOnSuccessListener(vt->{String t=vt.getText().toLowerCase();String r="Tidak terdeteksi";if(t.contains("100000")||t.contains("seratus ribu"))r="💵 SERATUS RIBU";else if(t.contains("50000")||t.contains("lima puluh"))r="💵 LIMA PULUH RIBU";else if(t.contains("20000"))r="💵 DUA PULUH RIBU";else if(t.contains("10000"))r="💵 SEPULUH RIBU";else if(t.contains("bank indonesia"))r="💵 Rupiah terdeteksi";else r="Teks: "+vt.getText();tvResult.setText(r);speak(r);});}
private void analyzeColor(Bitmap bm){try{int w=bm.getWidth(),h=bm.getHeight(),cx=w/2,cy=h/2;long rs=0,gs=0,bs=0;int cnt=0;for(int x=cx-50;x<cx+50;x+=5)for(int y=cy-50;y<cy+50;y+=5)if(x>=0&&x<w&&y>=0&&y<h){int p=bm.getPixel(x,y);rs+=Color.red(p);gs+=Color.green(p);bs+=Color.blue(p);cnt++;}int r=(int)(rs/cnt),g=(int)(gs/cnt),b=(int)(bs/cnt);String c=getColor(r,g,b);String res="🎨 Warna: "+c;tvResult.setText(res);speak(res);}catch(Exception e){}}
private String getColor(int r,int g,int b){if(r>200&&g>200&&b>200)return "Putih";if(r<50&&g<50&&b<50)return "Hitam";if(r>180&&g<100&&b<100)return "Merah";if(g>150&&r<100&&b<100)return "Hijau";if(b>150)return "Biru";if(r>180&&g>180&&b<100)return "Kuning";return "Campuran";}
private void analyzeFace(Bitmap bm){InputImage img=InputImage.fromBitmap(bm,0);FaceDetectorOptions op=new FaceDetectorOptions.Builder().setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_FAST).build();FaceDetection.getClient(op).process(img).addOnSuccessListener(fs->{String res=fs.isEmpty()?"Tidak ada orang":"Terdeteksi "+fs.size()+" orang";tvResult.setText(res);speak(res);});}
private void analyzeKtp(Bitmap bm){InputImage img=InputImage.fromBitmap(bm,0);TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS).process(img).addOnSuccessListener(vt->{String full=vt.getText();StringBuilder sb=new StringBuilder();sb.append("🪪 HASIL BACA KTP/KK:\n\n");String nik=extract(full,"NIK",16);String nama=extract(full,"Nama",30);if(full.toLowerCase().contains("nik")||full.matches(".*\\d{16}.*")){sb.append("Dokumen KTP terdeteksi\n");if(!nik.isEmpty())sb.append("NIK: ").append(nik).append("\n");if(!nama.isEmpty())sb.append("Nama: ").append(nama).append("\n");sb.append("\nTeks: ").append(full);}else sb.append(full);String res=sb.toString();if(res.length()>2000)res=res.substring(0,2000);tvResult.setText(res);String sp="Membacakan dokumen. ";if(!nik.isEmpty())sp+="NIK "+nik+". ";if(!nama.isEmpty())sp+="Nama "+nama+". ";speak(sp);});}
private String extract(String text,String key,int len){try{int idx=text.toLowerCase().indexOf(key.toLowerCase());if(idx<0)return"";int st=idx+key.length();int en=Math.min(text.length(),st+len);String sub=text.substring(st,en).replace(":","").trim();int nl=sub.indexOf("\n");if(nl>0)sub=sub.substring(0,nl);return sub.trim();}catch(Exception e){return"";}}
private void speak(String s){if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,null);}
@Override public void onInit(int st){if(st==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("id","ID"));tts.setSpeechRate(0.9f);}}
}
